-- gymgyme directory: table + RLS + seed. Paste into the Supabase SQL editor (shared damlahelloworld project).
create table if not exists hl_entries (
  id uuid primary key default gen_random_uuid(),
  kind text not null check (kind in ('link','exercise')),
  category text not null check (category in ('healthy-living-articles','home-workouts','pilates','ballet','yoga','gym','calisthenics','bodyweight')),
  title text not null check (char_length(title) between 2 and 200),
  url text check (url is null or url ~* '^https?://'),
  description text check (description is null or char_length(description) <= 500),
  how text check (how is null or char_length(how) <= 1000),
  contributor text not null check (char_length(contributor) between 1 and 60),
  recommend_count int not null default 1,
  approved boolean not null default false,
  created_at timestamptz not null default now()
);
alter table hl_entries enable row level security;
drop policy if exists hl_public_read on hl_entries;
create policy hl_public_read on hl_entries for select using (approved = true);
drop policy if exists hl_anon_suggest on hl_entries;
create policy hl_anon_suggest on hl_entries for insert with check (approved = false and recommend_count = 1);

